def analyse_text(text):
    # Check for common Carbon patterns that strongly indicate Carbon code
    if re.search(r'\bpackage\s+\w+\s*;', text) and re.search(r'\bfn\s+\w+\s*\(', text):
        return 0.8

    # Check for Carbon-specific keywords and patterns
    carbon_indicators = 0
    if 'package' in text:
        carbon_indicators += 1
    if re.search(r'\bfn\s+\w+', text):
        carbon_indicators += 1
    if re.search(r'\blet\s+\w+\s*=', text):
        carbon_indicators += 1

    # Check for Carbon-specific literals
    if re.search(r'\b0x[0-9a-fA-F]+[sl]?\b', text):
        carbon_indicators += 0.5
    if re.search(r'\b0b[01]+[sl]?\b', text):
        carbon_indicators += 0.5
    if re.search(r'\b0o[0-7]+[sl]?\b', text):
        carbon_indicators += 0.5

    # Return a score based on the number of indicators found
    if carbon_indicators >= 3:
        return 0.7
    elif carbon_indicators >= 1:
        return 0.3
    return 0.0
